{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "`create_shipment` needs the sender address (the account's `pickup_address`), the recipient address, the weight in kilograms and the service.",
      "requirement": "The `create_shipment` tool call must include the sender address as the account's registered `pickup_address` (Liivalaia 12, 10118 Tallinn, EE)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Weight must be given in kilograms. If the customer gives pounds, convert (1 lb = 0.4536 kg) and round to one decimal.",
      "requirement": "The weight must be provided in kilograms, converted from pounds if necessary, and rounded to one decimal place."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Prohibited items: batteries shipped loose (not inside a device), aerosols, and any liquids over 1 litre. Shipments containing prohibited items must not be created.",
      "requirement": "The shipment must not contain prohibited items: loose batteries, aerosols, or liquids exceeding 1 liter."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Declared value (insurance) may not exceed 2,000 EUR per parcel. Values above that are not accepted.",
      "requirement": "If a declared value (insurance) is provided, it must not exceed 2,000 EUR."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "The service `express` guarantees next-business-day delivery; `standard` takes 2–4 business days. When telling the customer the expected delivery date, compute it from today and the service (business days are Monday–Friday).",
      "requirement": "The service must be one of the allowed options (`standard` or `express`)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Before `create_shipment`, ... obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation from the user (\"yes\" or \"да\") must be obtained before proceeding with `create_shipment`."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Outside the EU, customs declarations are required and declared value may go up to 5,000 EUR with the `international` service only. Not applicable to domestic shipments.",
      "requirement": "For domestic shipments (both sender and recipient addresses within the EU), no customs declarations are required, and the declared value limit is 2,000 EUR."
    }
  ]
}
